/// <summary>
/// PaffH 13.05.22
/// expand label with AOTname
/// </summary>
/// <param name = "aotName">Name</param>
/// <param name = "nameValue">str</param>
/// <returns>role label</returns>
/// <remarks>
/// classes.SysSecRole.expandChildren(67)
/// </remarks>
public static str GetSecurityRoleLabel(Name aotName, str nameValue)
{
    str label = next GetSecurityRoleLabel(aotName, nameValue);
    return strFmt('%1 [%2]', label, aotName);
}
